import{_ as n,o as h,c as i,a5 as a}from"./chunks/framework.Bf1r8NYr.js";const p=JSON.parse('{"title":"Phụ lục cập nhật: Yêu cầu và mẫu nhà tài trợ","description":"","frontmatter":{},"headers":[],"relativePath":"course/book/appendices/funder-templates.md","filePath":"course/book/appendices/funder-templates.md"}'),c={name:"course/book/appendices/funder-templates.md"};function e(r,t,o,d,g,l){return h(),i("div",null,[...t[0]||(t[0]=[a(`<hr><h2 id="reviewed-2026-11-21next-review-2027-05-21" tabindex="-1">reviewed: 2026-11-21 next_review: 2027-05-21 <a class="header-anchor" href="#reviewed-2026-11-21next-review-2027-05-21" aria-label="Permalink to &quot;reviewed: 2026-11-21
next_review: 2027-05-21&quot;">​</a></h2><h1 id="phu-luc-cap-nhat-yeu-cau-va-mau-nha-tai-tro" tabindex="-1">Phụ lục cập nhật: Yêu cầu và mẫu nhà tài trợ <a class="header-anchor" href="#phu-luc-cap-nhat-yeu-cau-va-mau-nha-tai-tro" aria-label="Permalink to &quot;Phụ lục cập nhật: Yêu cầu và mẫu nhà tài trợ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Trạng thái</th><th>URL nguồn</th><th>Ngày kiểm</th><th>Ghi chú</th></tr></thead><tbody><tr><td>NIH Data Management and Sharing Policy (2023)</td><td>VERIFIED</td><td><a href="https://grants.nih.gov/grants/guide/notice-files/NOT-OD-21-013.html" target="_blank" rel="noreferrer">https://grants.nih.gov/grants/guide/notice-files/NOT-OD-21-013.html</a></td><td>2026-11-21</td><td>Chính sách vẫn giữ nguyên; định dạng kế hoạch đã thay đổi.</td></tr><tr><td>NOT-OD-26-046 — Updated Elements</td><td>VERIFIED_UNAUDITED</td><td><a href="https://grants.nih.gov/grants/guide/notice-files/NOT-OD-26-046.html" target="_blank" rel="noreferrer">https://grants.nih.gov/grants/guide/notice-files/NOT-OD-26-046.html</a></td><td>2026-11-21</td><td>NIH nêu định dạng mới, hiệu lực cho hồ sơ có hạn từ 25/05/2026 và gọi đây là pilot.</td></tr><tr><td>Trang định dạng DMS 2026 và hướng dẫn viết</td><td>VERIFIED_UNAUDITED</td><td><a href="https://grants.nih.gov/grants-process/write-application/forms-directory/data-management-and-sharing-plan-format-page" target="_blank" rel="noreferrer">https://grants.nih.gov/grants-process/write-application/forms-directory/data-management-and-sharing-plan-format-page</a>; <a href="https://grants.nih.gov/policy-and-compliance/policy-topics/sharing-policies/dms/writing-dms-plan" target="_blank" rel="noreferrer">https://grants.nih.gov/policy-and-compliance/policy-topics/sharing-policies/dms/writing-dms-plan</a></td><td>2026-11-21</td><td>Đã đọc nguồn NIH chính thức; trạng thái giữ ở mức kiểm toán nội dung chưa hoàn tất.</td></tr><tr><td>NOT-OD-26-100 — chuyển tiếp và báo cáo</td><td>VERIFIED_UNAUDITED</td><td><a href="https://www.grants.nih.gov/grants/guide/notice-files/NOT-OD-26-100.html" target="_blank" rel="noreferrer">https://www.grants.nih.gov/grants/guide/notice-files/NOT-OD-26-100.html</a></td><td>2026-11-21</td><td>Dùng để đối chiếu phạm vi áp dụng cho hồ sơ/giải thưởng đang chuyển tiếp.</td></tr><tr><td>NOT-OD-22-213 — bảo vệ quyền riêng tư</td><td>VERIFIED_UNAUDITED</td><td><a href="https://grants.nih.gov/grants/guide/notice-files/NOT-OD-22-213.html" target="_blank" rel="noreferrer">https://grants.nih.gov/grants/guide/notice-files/NOT-OD-22-213.html</a></td><td>2026-11-21</td><td>Nguồn NIH chính thức được viện dẫn tại yếu tố 5.</td></tr><tr><td>Tên mẫu hiển thị trên DMPTool</td><td>CONTENT_PENDING</td><td><a href="https://dmptool.org/public_templates" target="_blank" rel="noreferrer">https://dmptool.org/public_templates</a>; <a href="https://dmptool.org/public_plans?all=true" target="_blank" rel="noreferrer">https://dmptool.org/public_plans?all=true</a></td><td>2026-11-21</td><td>Bản đọc từ môi trường staging từng hiển thị “NIH 2026 Data Management and Sharing Plan (2026 Pilot Format, required starting May 25, 2026)”. Trang production được kiểm tra ngày 21/11/2026 đang hiển thị “NIH Data Management and Sharing Plan (2026 Pilot DMS Format)”; tên mẫu có thể thay đổi, cần kiểm tra lại trước khi dạy. Không dùng URL staging trong phụ lục.</td></tr><tr><td>Horizon Europe</td><td>BIB_PENDING</td><td><a href="https://ec.europa.eu/research/participants/documents/downloadPublic?documentIds=080166e519589e89&amp;appId=PPGMS" target="_blank" rel="noreferrer">https://ec.europa.eu/research/participants/documents/downloadPublic?documentIds=080166e519589e89&amp;appId=PPGMS</a></td><td>2026-11-21</td><td>Chi tiết mẫu và mốc nộp cần kiểm theo tài liệu gốc.</td></tr><tr><td>FAIR Cookbook</td><td>BIB_PENDING</td><td><a href="https://faircookbook.elixir-europe.org/" target="_blank" rel="noreferrer">https://faircookbook.elixir-europe.org/</a></td><td>2026-11-21</td><td>Tài liệu hỗ trợ thực hành FAIR; phiên bản/phạm vi áp dụng chưa chốt.</td></tr></tbody></table><h2 id="đinh-dang-nih-2026" tabindex="-1">Định dạng NIH 2026 <a class="header-anchor" href="#đinh-dang-nih-2026" aria-label="Permalink to &quot;Định dạng NIH 2026&quot;">​</a></h2><p>NIH xác nhận chính sách DMS 2023 không đổi; thay đổi chủ yếu là mẫu trình bày. Định dạng 2026 được yêu cầu cho hồ sơ và báo cáo thuộc phạm vi NIH theo mốc chuyển tiếp, nhưng NOFO cụ thể vẫn phải được đọc cùng chính sách nhà tài trợ. Bảy yếu tố dưới đây được tóm tắt bằng lời của phụ lục; câu tiếng Anh ngắn được giữ để đối chiếu với nguồn NIH chính thức.</p><table tabindex="0"><thead><tr><th>Yếu tố</th><th>Tóm tắt tiếng Việt</th><th>English wording (short)</th><th>Trả lời/giới hạn</th></tr></thead><tbody><tr><td>1</td><td>Có chia sẻ tối đa phù hợp dữ liệu khoa học làm nền cho công bố và phát hiện khác không?</td><td>“Will there be maximum appropriate sharing of scientific data…?”</td><td>Có/Không</td></tr><tr><td>2</td><td>Dữ liệu có được chia sẻ vào thời điểm công bố hoặc trước khi kết thúc thời gian thực hiện, kể cả gia hạn không tốn chi phí, không?</td><td>“Will the scientific data… be shared by the time of publication…?”</td><td>Có/Không</td></tr><tr><td>3</td><td>Dữ liệu đã chia sẻ có được duy trì ít nhất theo yêu cầu của kho và/hoặc tạp chí không?</td><td>“Will shared scientific data be made available for at least as long as required…?”</td><td>Có/Không</td></tr><tr><td>4</td><td>Nếu có giới hạn, giải thích giới hạn và yếu tố đạo đức, pháp lý hoặc kỹ thuật cụ thể.</td><td>“Please describe these limitations and the ethical, legal, or technical factors…”</td><td>Tường thuật; giới hạn 300 từ theo nguồn thứ cấp [CẦN KIỂM CHỨNG: chưa xác nhận trên mẫu NIH gốc]</td></tr><tr><td>5</td><td>Nếu có dữ liệu người tham gia, quyền riêng tư, quyền và bảo mật có được bảo vệ theo NOT-OD-22-213, kể cả kiểm soát truy cập, không?</td><td>“Will privacy, rights, and confidentiality… be protected as outlined in NOT-OD-22-213…?”</td><td>Có/Không/Không áp dụng</td></tr><tr><td>6</td><td>Lập bảng các loại dữ liệu khoa học chính, kèm loài/phương thức nếu biết, và kho đã thiết lập hoặc ví dụ kho.</td><td>“In table format, please list…”</td><td>Bảng, tối đa 100 từ</td></tr><tr><td>7a</td><td>Với nghiên cứu thuộc GDS, có chia sẻ dữ liệu genomics người hoặc không phải người quy mô lớn và dữ liệu liên quan vào kho NIH chỉ định theo tiến độ GDS không?</td><td>“Will you share all large-scale human or non-human genomic and associated data…?”</td><td>Có/Không/Không áp dụng</td></tr><tr><td>7b</td><td>Có dự kiến đáp ứng kỳ vọng của Institutional Certification khi chia sẻ genomics người quy mô lớn không?</td><td>“Do you anticipate… meet the expectations of the Institutional Certification…?”</td><td>Có/Không/Không áp dụng</td></tr></tbody></table><p>Nguồn chính cho bảng: NOT-OD-26-046 và trang hướng dẫn NIH, đã kiểm ngày 21/11/2026. <code>VERIFIED_UNAUDITED</code> không có nghĩa là đã hoàn tất kiểm toán nội dung độc lập.</p><blockquote><p><strong>Chưa xác nhận:</strong> giới hạn 300 từ gắn với yếu tố 4 đến từ nguồn thứ cấp (DMPTool, trang thư viện). Giới hạn 100 từ của bảng yếu tố 6 đã khớp trang định dạng NIH (đọc ngày 21/11/2026). Cần mở tệp mẫu DOCX chính thức của NIH để xác nhận từ nào có giới hạn 300 từ trước khi dạy hoặc ghi vào bài tập (<code>CONTENT_PENDING</code>).</p></blockquote><h3 id="huong-dan-kem-mau-đang-chu-y" tabindex="-1">Hướng dẫn kèm mẫu đáng chú ý <a class="header-anchor" href="#huong-dan-kem-mau-đang-chu-y" aria-label="Permalink to &quot;Hướng dẫn kèm mẫu đáng chú ý&quot;">​</a></h3><ul><li><strong>Giới hạn chia sẻ:</strong> lý do có thể chính đáng gồm giới hạn của đồng thuận, nguy cơ tái nhận diện mà khử định danh và biện pháp bảo vệ không đủ, luật/quy định cấm tiết lộ, hạn chế trong thỏa thuận hoặc dữ liệu không thể số hóa với nỗ lực hợp lý. “Dữ liệu ít”, ít người dùng hoặc chưa tìm được kho không tự nó là lý do chính đáng. Nguồn: trang hướng dẫn NIH, kiểm ngày 21/11/2026.</li><li><strong>NOT-OD-22-213:</strong> kế hoạch phải xem xét chủ động việc bảo vệ, thông tin rõ trong đồng thuận, giới hạn chia sẻ hợp lý, rà soát của IRB, biện pháp bảo vệ cho mọi dữ liệu dùng trong nghiên cứu và nguy cơ lạm dụng.</li><li><strong>Kho lưu trữ:</strong> ưu tiên kho chuyên ngành hoặc kho phù hợp với loại dữ liệu; kho tổng quát như Zenodo, Dryad hoặc Figshare chỉ là phương án khi không có kho chuyên ngành phù hợp. Ví dụ kho trong hướng dẫn là minh họa, không thay thế yêu cầu của NIH hoặc NOFO.</li><li><strong>GDS:</strong> yếu tố 7a/7b chỉ áp dụng khi nghiên cứu thuộc GDS; cần chú ý kho NIH chỉ định, thời hạn nộp và Institutional Certification. Không suy ra rằng mọi nghiên cứu đều phải có dữ liệu genomics.</li></ul><p>Đây là hướng dẫn trên DMPTool và nguồn thứ cấp đã được dùng để định hướng nội dung; các câu hỏi và giới hạn đã được đối chiếu với nguồn NIH chính thức ngày 21/11/2026. Người nghiên cứu vẫn phải đọc chính sách nhà tài trợ và NOFO cụ thể. Định dạng mới không làm giảm nghĩa vụ lập kế hoạch, dự toán và quản lý dữ liệu.</p><h2 id="mau-nih-cu-va-pham-vi-chuyen-tiep" tabindex="-1">Mẫu NIH cũ và phạm vi chuyển tiếp <a class="header-anchor" href="#mau-nih-cu-va-pham-vi-chuyen-tiep" aria-label="Permalink to &quot;Mẫu NIH cũ và phạm vi chuyển tiếp&quot;">​</a></h2><p>Mẫu tường thuật NIH 2023/legacy chỉ nên được xem như mẫu lịch sử hoặc dùng khi hồ sơ nằm trong trường hợp chuyển tiếp được văn bản NIH/NOFO cho phép. Điều kiện áp dụng chi tiết của mẫu cũ và quan hệ với NOT-OD-26-100 chưa được chốt hoàn toàn trong phụ lục này: <strong>CONTENT_PENDING</strong>. Không dùng mẫu cũ như chuẩn hiện hành cho bài lab.</p><h2 id="cach-xac-đinh-ten-mau-tren-dmptool" tabindex="-1">Cách xác định tên mẫu trên DMPTool <a class="header-anchor" href="#cach-xac-đinh-ten-mau-tren-dmptool" aria-label="Permalink to &quot;Cách xác định tên mẫu trên DMPTool&quot;">​</a></h2><p>Tên mẫu nêu trong bảng trạng thái là thông tin quan sát từ DMPTool, không phải tên pháp lý cố định của NIH. Production <code>dmptool.org</code> đã được kiểm ngày 21/11/2026 và hiển thị tên ngắn hơn tên từng thấy trong môi trường staging. Trước mỗi lớp, mở production, kiểm tra tên và ngày cập nhật, rồi chọn mẫu NIH hiện hành; không suy ra tên từ ảnh chụp hoặc bản xuất cũ.</p><h2 id="luu-y-su-dung" tabindex="-1">Lưu ý sử dụng <a class="header-anchor" href="#luu-y-su-dung" aria-label="Permalink to &quot;Lưu ý sử dụng&quot;">​</a></h2><p>DMPTool là lớp hỗ trợ soạn thảo dựa trên chính sách nhà tài trợ; người nghiên cứu phải đối chiếu trực tiếp chính sách và NOFO cụ thể. Thời hạn lưu giữ hồ sơ 3 năm của NIH/HHS là yêu cầu lưu giữ hồ sơ tài trợ, không được gọi là “NIH DMS Policy” một cách khái quát; xem <a href="/biomedical-rdm-course/course/book/appendices/retention.html"><code>retention.md</code></a>. Mốc này không áp dụng mặc nhiên cho đề tài trong nước và không được lẫn với 25 năm theo EU 536/2014 hoặc các mốc 30/20 năm của Thông tư 33/2025 đang <code>CONTENT_PENDING</code>.</p><h3 id="mau-cua-nha-tai-tro-khac" tabindex="-1">Mẫu của nhà tài trợ khác <a class="header-anchor" href="#mau-cua-nha-tai-tro-khac" aria-label="Permalink to &quot;Mẫu của nhà tài trợ khác&quot;">​</a></h3><p>Mẫu trên DMPTool có hạn sử dụng và có thể bị gắn nhãn OUTDATED khi chính sách thay đổi. Luôn kiểm tra ngày cập nhật và văn bản nhà tài trợ trước khi dùng; phụ lục này không coi danh sách mẫu khác là bằng chứng hiện hành.</p>`,20)])])}const s=n(c,[["render",e]]);export{p as __pageData,s as default};
